const currentItem = $input.first();
const current = currentItem.json || {};

let original = {};
try {
  original = $('Decide AI mode').first().json || {};
} catch (e) {
  original = {};
}

const item = {
  ...original,
  ...current,

  user_id: original.user_id || current.user_id,
  chat_id: original.chat_id || current.chat_id,
  pending_message_id: original.pending_message_id || current.pending_message_id,
  message_uuid: original.message_uuid || current.message_uuid,

  message_type: original.message_type || current.message_type,
  file_id: original.file_id || current.file_id,
  file_unique_id: original.file_unique_id || current.file_unique_id,
  file_name: original.file_name || current.file_name,
  mime_type: original.mime_type || current.mime_type,
  caption: original.caption || current.caption,
  message: original.message || current.message,
  content: original.content || current.content,

  telegram_file_path:
    current.result?.file_path ||
    current.file_path ||
    original.telegram_file_path ||
    current.telegram_file_path,

  file_url: original.file_url || current.file_url
};

function firstValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return null;
}

function safeString(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  return String(value);
}

function getExtension(fileName) {
  const match = safeString(fileName).toLowerCase().match(/\.([a-z0-9]+)$/);
  return match ? match[1] : '';
}

function truncateText(text, maxChars) {
  const str = safeString(text);
  if (str.length <= maxChars) return str;
  return str.slice(0, maxChars) + `\n\n[Content truncated to ${maxChars} characters]`;
}

function normalizeMimeType(mimeType, ext, messageType) {
  const mt = safeString(mimeType).toLowerCase();

  if (mt && mt !== 'application/octet-stream') return mt;

  if (messageType === 'photo') {
    if (ext === 'png') return 'image/png';
    if (ext === 'webp') return 'image/webp';
    if (ext === 'heic') return 'image/heic';
    return 'image/jpeg';
  }

  if (ext === 'jpg' || ext === 'jpeg') return 'image/jpeg';
  if (ext === 'png') return 'image/png';
  if (ext === 'webp') return 'image/webp';
  if (ext === 'heic') return 'image/heic';
  if (ext === 'pdf') return 'application/pdf';

  return mimeType || 'application/octet-stream';
}

async function findBinaryData() {
  const binary = currentItem.binary || {};
  const keys = Object.keys(binary);

  if (!keys.length) return null;

  const propertyName = keys.includes('data') ? 'data' : keys[0];
  const binaryMeta = binary[propertyName];

  if (!binaryMeta) return null;

  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, propertyName);

    return {
      data: buffer.toString('base64'),
      mimeType: binaryMeta.mimeType || binaryMeta.mime_type || null,
      fileName: binaryMeta.fileName || binaryMeta.file_name || null,
      fileSize: buffer.length,
      propertyName
    };
  } catch (error) {
    return null;
  }
}

const userId = firstValue(item.user_id, item.from_id);
const chatId = firstValue(item.chat_id, userId);
const pendingMessageId = firstValue(item.pending_message_id, item.id);
const messageUuid = firstValue(item.message_uuid);

const messageType = safeString(item.message_type || 'document').toLowerCase();

let fileName = safeString(
  item.file_name ||
  item.message ||
  item.content ||
  item.telegram_file_path ||
  'file'
);

if (messageType === 'photo' && (!fileName || fileName === '[photo]')) {
  fileName = 'photo.jpg';
}

const ext = getExtension(fileName || item.telegram_file_path);

let mimeType = safeString(item.mime_type || 'application/octet-stream');
mimeType = normalizeMimeType(mimeType, ext, messageType);

const caption = safeString(item.caption || '');
const telegramFilePath = safeString(item.telegram_file_path || '');
const fileUrl = safeString(item.file_url || '');

const binaryData = await findBinaryData();

if (binaryData?.mimeType) {
  mimeType = normalizeMimeType(binaryData.mimeType, ext, messageType);
}

const supportedGeminiInlineMimeTypes = [
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/heic',
  'application/pdf'
];

const hasInlineData =
  Boolean(binaryData?.data) &&
  supportedGeminiInlineMimeTypes.includes(mimeType);

const readableContent = truncateText(
  safeString(
    item.extracted_text ||
    item.file_text ||
    item.downloaded_text ||
    item.text_content ||
    item.content_for_ai ||
    caption ||
    ''
  ),
  12000
);

const oldBinaryExtensions = ['doc', 'xls', 'ppt'];
const skipGeminiAnalysis =
  item.should_analyze_file === false ||
  (oldBinaryExtensions.includes(ext) && !readableContent);

const fallbackBusinessCardData = {
  is_business_card: false,
  person_name: null,
  company: null,
  logo_text: null,
  position: null,
  business_activity: null,
  market_role: null,
  imported_products: [],
  product_categories: [],
  brands_or_products: [],
  phone: null,
  email: null,
  wechat: null,
  website: null,
  address: null,
  country: null,
  notes: null
};

if (skipGeminiAnalysis) {
  return [
    {
      json: {
        ...item,
        user_id: userId,
        chat_id: chatId,
        pending_message_id: pendingMessageId,
        message_uuid: messageUuid,
        message_type: messageType,
        file_name: fileName,
        mime_type: mimeType,
        caption,
        telegram_file_path: telegramFilePath,
        file_url: fileUrl,
        file_extension: ext,

        ai_mode: 'fallback',
        should_analyze_file: false,
        skip_gemini_analysis: true,

        ai_summary: `File saved: ${fileName}`,
        ai_category: 'file',
        ai_detected_type: 'file',
        ai_language: 'unknown',
        ai_entities: [],
        ai_important_details: [],
        ai_confidence: 0.3,
        ai_business_card_data: fallbackBusinessCardData
      }
    }
  ];
}

const prompt = `
You are an AI metadata extractor for a personal Telegram memory bot called Memoraq.

Analyze the attached image/file/PDF and return ONLY a raw JSON object.

CRITICAL OCR RULES:
- Visually inspect the image/document.
- Read all visible text.
- Detect the language of the ORIGINAL visible text.
- Hebrew characters => "he"
- Cyrillic characters => "ru"
- Chinese Hanzi => "zh"
- Do not default to English because this prompt is in English.

BUSINESS / COMPANY CARD RULE:
If the image/document looks like a business card, name card, company profile card, product card, distributor card, importer card, exhibition card, product presentation card, or any compact card with logo/company name/business activities/contact/product list, set:

category = "business_card"
detected_type = "business_card"
business_card_data.is_business_card = true

This rule applies even if there is no person name, phone, email, or contact details.

Extract visible business fields:
- company name / brand
- logo text
- person name if visible
- position if visible
- business activity
- market role, for example importer, distributor, agent, general agent
- imported products
- product categories
- brands/products mentioned
- country/market
- phone/email/website/wechat/address if visible

If a field is not visible, use null.

FILE CONTEXT:
File name: ${fileName}
MIME type: ${mimeType}
Caption: ${caption || 'none'}
Readable text if available:
${readableContent || 'none'}

Return strictly this JSON schema:
{
  "summary": "1 short sentence in English, max 220 characters, only the core meaning.",
  "category": "business_card | document | photo | legal | finance | technical | career | travel | personal | shopping | task | note | other",
  "detected_type": "business_card | document | photo | screenshot | receipt | contract | certificate | presentation | spreadsheet | file | other",
  "language": "two-letter ISO 639-1 code: he | ru | en | zh | unknown",
  "entities": ["people, companies, brands, places, products, technologies, IDs, URLs"],
  "important_details": [
    {
      "label": "date | amount | company | person | location | phone | email | position | document_number | product | link | technology | other",
      "value": "important detail value"
    }
  ],
  "visible_or_extracted_text": "cleaned original visible text or null",
  "business_card_data": {
    "is_business_card": false,
    "person_name": null,
    "company": null,
    "logo_text": null,
    "position": null,
    "business_activity": null,
    "market_role": null,
    "imported_products": [],
    "product_categories": [],
    "brands_or_products": [],
    "phone": null,
    "email": null,
    "wechat": null,
    "website": null,
    "address": null,
    "country": null,
    "notes": null
  },
  "confidence": 0.85
}

Rules:
- Do not include markdown.
- Do not include explanations.
- JSON only.
`.trim();

const parts = [{ text: prompt }];

if (hasInlineData) {
  parts.push({
    inline_data: {
      mime_type: mimeType,
      data: binaryData.data
    }
  });
}

const geminiRequestBody = {
  contents: [
    {
      role: 'user',
      parts
    }
  ],
  generationConfig: {
    temperature: 0.05,
    topK: 1,
    topP: 0.1,
    maxOutputTokens: 2048,
    responseMimeType: 'application/json'
  }
};

return [
  {
    json: {
      ...item,
      user_id: userId,
      chat_id: chatId,
      pending_message_id: pendingMessageId,
      message_uuid: messageUuid,
      message_type: messageType,
      file_name: fileName,
      mime_type: mimeType,
      caption,
      telegram_file_path: telegramFilePath,
      file_url: fileUrl,
      file_extension: ext,

      is_image_file: mimeType.startsWith('image/'),
      has_inline_image: hasInlineData,

      ai_mode: 'file',
      should_analyze_file: true,
      skip_gemini_analysis: false,

      gemini_request_body: geminiRequestBody,
      gemini_parts_count: parts.length
    }
  }
];

const item = $input.first().json || {};

const metadata =
  item.fallback_metadata ||
  {
    summary: item.ai_summary || `File saved: ${item.file_name || 'file'}`,
    category: item.ai_category || 'file',
    language: item.ai_language || 'unknown',
    keywords: item.ai_keywords || [item.file_name || 'file'],
    entities: item.ai_entities || [],
    important_details: item.ai_important_details || [],
    confidence: item.ai_confidence || 0.3
  };

return [
  {
    json: {
      ...item,

      ai_mode: 'fallback',
      gemini_failed: false,
      gemini_skipped: true,

      ai_summary: metadata.summary,
      ai_category: metadata.category,
      ai_language: metadata.language,
      ai_keywords: metadata.keywords,
      ai_entities: metadata.entities,
      ai_important_details: metadata.important_details,
      ai_confidence: metadata.confidence,

      ai_raw_json: {
        fallback: true,
        reason: item.skip_gemini_reason || 'gemini_analysis_skipped',
        file_name: item.file_name,
        mime_type: item.mime_type,
        extension: item.file_extension
      },

      ai_raw_text: JSON.stringify(metadata),
      text: JSON.stringify(metadata)
    }
  }
];

const input = $input.first().json || {};

let source = {};
try {
  source = $('Prepare Gemini file request').first().json || {};
} catch (e) {
  source = {};
}

function safeString(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  return String(value);
}

function cleanString(value, maxLength = 1000) {
  const str = safeString(value).replace(/\s+/g, ' ').trim();
  if (str.length <= maxLength) return str;
  return str.slice(0, maxLength).trim();
}

function stripCodeFences(text) {
  return safeString(text)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function parseJsonFromText(text) {
  const raw = stripCodeFences(text);
  if (!raw) return null;

  try {
    return JSON.parse(raw);
  } catch (e) {}

  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      return JSON.parse(match[0]);
    } catch (e) {}
  }

  return null;
}

function extractGeminiText(response) {
  if (response.candidates?.[0]?.content?.parts?.[0]?.text) {
    return response.candidates[0].content.parts[0].text;
  }

  if (response.text) return response.text;

  if (typeof response === 'string') return response;

  return JSON.stringify(response);
}

function normalizeArray(value) {
  if (Array.isArray(value)) {
    return value
      .map(v => {
        if (v === null || v === undefined) return '';
        if (typeof v === 'object') return JSON.stringify(v);
        return String(v);
      })
      .map(v => v.trim())
      .filter(Boolean);
  }

  if (value === null || value === undefined || value === '') return [];

  return [String(value).trim()].filter(Boolean);
}

function uniqueArray(values) {
  return [...new Set(values.map(v => String(v).trim()).filter(Boolean))];
}

function extractByRegex(text, patterns) {
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      return match[1].replace(/[：:]/g, '').trim();
    }
  }
  return null;
}

function normalizeBusinessCardData(value, parsed = {}, fullText = '') {
  const empty = {
    is_business_card: false,
    person_name: null,
    company: null,
    logo_text: null,
    position: null,
    business_activity: null,
    market_role: null,
    imported_products: [],
    product_categories: [],
    brands_or_products: [],
    phone: null,
    email: null,
    wechat: null,
    website: null,
    address: null,
    country: null,
    notes: null
  };

  const arr = v => {
    if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
    if (v === null || v === undefined || v === '') return [];
    return [String(v).trim()].filter(Boolean);
  };

  let card = { ...empty };

  if (value && typeof value === 'object' && !Array.isArray(value)) {
    card = {
      ...card,
      is_business_card: Boolean(value.is_business_card),
      person_name: value.person_name || null,
      company: value.company || null,
      logo_text: value.logo_text || null,
      position: value.position || null,
      business_activity: value.business_activity || null,
      market_role: value.market_role || null,
      imported_products: arr(value.imported_products),
      product_categories: arr(value.product_categories),
      brands_or_products: arr(value.brands_or_products),
      phone: value.phone || null,
      email: value.email || null,
      wechat: value.wechat || null,
      website: value.website || null,
      address: value.address || null,
      country: value.country || null,
      notes: value.notes || null
    };
  }

  const details = Array.isArray(parsed.important_details)
    ? parsed.important_details
    : [];

  for (const d of details) {
    const label = String(d.label || '').toLowerCase();
    const val = d.value ? String(d.value).trim() : '';
    if (!val) continue;

    if (!card.company && /company|公司/.test(label)) card.company = val;
    if (!card.person_name && /person|name|姓名|联系人/.test(label)) card.person_name = val;
    if (!card.position && /position|title|职位/.test(label)) card.position = val;
    if (!card.phone && /phone|mobile|tel|电话|手机/.test(label)) card.phone = val;
    if (!card.email && /email|mail|邮箱/.test(label)) card.email = val;
    if (!card.wechat && /wechat|weixin|微信/.test(label)) card.wechat = val;
    if (!card.website && /website|url|site|网址/.test(label)) card.website = val;
    if (!card.address && /address|地址/.test(label)) card.address = val;
    if (!card.country && /country|market|国家|市场/.test(label)) card.country = val;
  }

  const text = [
    fullText,
    parsed.summary,
    parsed.visible_or_extracted_text,
    JSON.stringify(parsed.entities || []),
    JSON.stringify(parsed.important_details || []),
    JSON.stringify(parsed.business_card_data || {})
  ]
    .filter(Boolean)
    .join('\n');

  const compactText = text.replace(/\r/g, '\n');

  if (!card.person_name) {
    card.person_name = extractByRegex(compactText, [
      /^([\u4e00-\u9fff]{2,5})\s*\n/,
      /姓名[：:\s]*([\u4e00-\u9fff]{2,8})/,
      /联系人[：:\s]*([\u4e00-\u9fff]{2,8})/,
      /Business card for\s+([A-Za-z\u4e00-\u9fff\s]+?)(?:\s+of|,|，|\n|$)/i
    ]);
  }

  if (!card.company) {
    card.company = extractByRegex(compactText, [
      /([\u4e00-\u9fff]{2,}(?:有限公司|经贸有限公司|贸易有限公司|商贸有限公司))/,
      /公司名称[：:\s]*([^\n]+)/,
      /公司[：:\s]*([^\n]+(?:有限公司|公司))/,
      /([A-Za-z0-9\s.,&-]*(?:Co\.?\s*Ltd\.?|Ltd\.?|Trade|Trading)[A-Za-z0-9\s.,&-]*)/i
    ]);
  }

  if (!card.logo_text) {
    card.logo_text = extractByRegex(compactText, [
      /(CHIHENG\s+TRADE)/i,
      /(驰恒经贸)/,
      /(LADOGA)/i
    ]);
  }

  if (!card.phone) {
    const phonePairs = compactText.match(/\d{7,15}(?:\s*\/\s*\d{7,15})?/g);
    if (phonePairs && phonePairs.length) {
      card.phone = phonePairs[0].replace(/\s+/g, '');
    }
  }

  if (!card.email) {
    const emailMatch = compactText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    if (emailMatch) {
      card.email = emailMatch[0];
    }
  }

  if (!card.wechat) {
    card.wechat = extractByRegex(compactText, [
      /微信号[：:\s]*([A-Za-z0-9_-]{3,})/i,
      /微信[：:\s]*([A-Za-z0-9_-]{3,})/i,
      /wechat[：:\s]*([A-Za-z0-9_-]{3,})/i,
      /weixin[：:\s]*([A-Za-z0-9_-]{3,})/i
    ]);
  }

  if (!card.wechat) {
    const wechatPhoneMatch = compactText.match(/\/\s*(\d{7,15})\s*[（(]\s*微信\s*[）)]/);
    if (wechatPhoneMatch) {
      card.wechat = wechatPhoneMatch[1];
    }
  }

  if (!card.address) {
    const companyAddress = extractByRegex(compactText, [
      /公司地址[：:\s]*([^\n]+)/,
      /地址[：:\s]*([^\n]+)/,
      /Address[：:\s]*([^\n]+)/i
    ]);

    const showroomAddress = extractByRegex(compactText, [
      /展厅地址[：:\s]*([^\n]+)/,
      /展厅[：:\s]*([^\n]+)/
    ]);

    if (companyAddress && showroomAddress) {
      card.address = `Company: ${companyAddress}; Showroom: ${showroomAddress}`;
    } else {
      card.address = companyAddress || showroomAddress || null;
    }
  }

  if (!card.country && /中国|黑龙江|绥芬河|China/i.test(compactText)) {
    card.country = 'China';
  }

  if (!card.business_activity && /经贸|贸易|trade|trading/i.test(compactText)) {
    card.business_activity = 'Trading / import-export business';
  }

  if (!card.market_role && /代理|总代理|agent|importer|distributor/i.test(compactText)) {
    card.market_role = 'Agent / distributor';
  }

  const productWords = [];
  const productMatches = compactText.match(/RussianTsar|Tsar|LADOGA|водка|vodka|酒|食品|进口产品/gi);
  if (productMatches) productWords.push(...productMatches);

  card.brands_or_products = uniqueArray([
    ...card.brands_or_products,
    ...productWords
  ]);

  const hasAnyField = [
    card.person_name,
    card.company,
    card.logo_text,
    card.position,
    card.business_activity,
    card.market_role,
    card.phone,
    card.email,
    card.wechat,
    card.website,
    card.address,
    card.country,
    card.imported_products.length,
    card.product_categories.length,
    card.brands_or_products.length
  ].some(Boolean);

  if (hasAnyField) {
    card.is_business_card = true;
  }

  return card;
}

const rawText = extractGeminiText(input);
const parsed = parseJsonFromText(rawText) || {};

const visibleText = parsed.visible_or_extracted_text || null;

const fullTextForExtraction = [
  rawText,
  visibleText,
  parsed.summary,
  JSON.stringify(parsed)
]
  .filter(Boolean)
  .join('\n');

const businessCardData = normalizeBusinessCardData(
  parsed.business_card_data,
  parsed,
  fullTextForExtraction
);

const combinedText = [
  fullTextForExtraction,
  JSON.stringify(businessCardData)
]
  .filter(Boolean)
  .join(' ')
  .toLowerCase();

const looksLikeBusinessCard =
  combinedText.includes('business card') ||
  combinedText.includes('company card') ||
  combinedText.includes('profile card') ||
  combinedText.includes('product card') ||
  combinedText.includes('distributor') ||
  combinedText.includes('importer') ||
  combinedText.includes('general agent') ||
  combinedText.includes('agent') ||
  combinedText.includes('import') ||
  combinedText.includes('main business') ||
  combinedText.includes('business activity') ||
  combinedText.includes('market role') ||
  combinedText.includes('主营业务') ||
  combinedText.includes('公司') ||
  combinedText.includes('代理') ||
  combinedText.includes('总代理') ||
  combinedText.includes('进口') ||
  combinedText.includes('经销') ||
  combinedText.includes('产品') ||
  combinedText.includes('业务') ||
  combinedText.includes('电话') ||
  combinedText.includes('邮箱') ||
  combinedText.includes('微信') ||
  combinedText.includes('地址') ||
  combinedText.includes('chiheng trade') ||
  combinedText.includes('驰恒经贸');

const parsedCategory = cleanString(parsed.category || '').toLowerCase();
const parsedDetectedType = cleanString(parsed.detected_type || '').toLowerCase();

const isBusinessCard =
  businessCardData.is_business_card === true ||
  parsedCategory === 'business_card' ||
  parsedDetectedType === 'business_card' ||
  looksLikeBusinessCard;

if (isBusinessCard) {
  businessCardData.is_business_card = true;
}

let category = cleanString(
  parsed.category ||
  input.ai_category ||
  (isBusinessCard ? 'business_card' : 'document'),
  80
).toLowerCase();

let detectedType = cleanString(
  parsed.detected_type ||
  input.ai_detected_type ||
  category ||
  'document',
  80
).toLowerCase();

if (isBusinessCard) {
  category = 'business_card';
  detectedType = 'business_card';
}

let language = cleanString(
  parsed.language ||
  input.ai_language ||
  'unknown',
  20
).toLowerCase();

if (/[\u4e00-\u9fff]/.test(fullTextForExtraction)) {
  language = 'zh';
} else if (/[\u0590-\u05FF]/.test(fullTextForExtraction)) {
  language = 'he';
} else if (/[А-Яа-яЁё]/.test(fullTextForExtraction)) {
  language = 'ru';
}

let summary = cleanString(
  parsed.summary ||
  input.ai_summary ||
  `File analyzed: ${source.file_name || 'file'}`,
  600
);

if (isBusinessCard) {
  const parts = [];

  if (businessCardData.person_name) parts.push(`contact: ${businessCardData.person_name}`);
  if (businessCardData.company) parts.push(`company: ${businessCardData.company}`);
